let triggerInput = {};
try {
  triggerInput = $('webhook-openrouter-trigger').first().json.body || $('Webhook Trigger').first().json.body || $json.body || {};
} catch (e) {
  triggerInput = $json.body || {};
}

const httpResponse = $json;

if (httpResponse.statusCode === 401 || httpResponse.error || (httpResponse.body && httpResponse.body.error)) {
  const errMsg = httpResponse.body?.error?.message || httpResponse.error || 'Unauthorized: Invalid OpenRouter Management API Key.';
  return {
    success: false,
    error: errMsg
  };
}

const rawData = httpResponse.body?.data || httpResponse.data || [];

if (Array.isArray(rawData)) {
  let totalUsage = 0;
  let totalLimit = 0;
  let hasLimits = false;
  let totalRemaining = 0;

  const parsedKeys = rawData.map(k => {
    const u = typeof k.usage === 'number' ? k.usage : 0;
    const l = typeof k.limit === 'number' ? k.limit : null;
    const r = typeof k.limit_remaining === 'number' ? k.limit_remaining : (l !== null ? Math.max(0, l - u) : null);

    totalUsage += u;
    if (l !== null) {
      totalLimit += l;
      hasLimits = true;
    }
    if (r !== null) {
      totalRemaining += r;
    }

    return {
      name: k.name || 'Unnamed Key',
      label: k.label || '',
      usage: Number(u.toFixed(4)),
      limit: l !== null ? Number(l.toFixed(2)) : null,
      remaining: r !== null ? Number(r.toFixed(4)) : null,
      createdAt: k.created_at || null,
      disabled: Boolean(k.disabled)
    };
  });

  const connectionId = 'or_conn_' + Math.random().toString(36).substring(2, 10);

  return {
    success: true,
    connectionId: connectionId,
    connectionName: triggerInput.connectionName || 'Enterprise OpenRouter Gateway',
    productTag: 'SHARED_GATEWAY',
    workspaceId: rawData[0]?.workspace_id || 'shared_workspace',
    totalUsage: Number(totalUsage.toFixed(2)),
    creditLimit: hasLimits ? Number(totalLimit.toFixed(2)) : null,
    remainingBalance: hasLimits ? Number(totalRemaining.toFixed(2)) : null,
    keyLabel: 'Workspace Provisioning Key',
    isFreeTier: false,
    recordsIngested: parsedKeys.length,
    keysList: parsedKeys,
    lastSyncedAt: new Date().toISOString()
  };
}

const keyData = rawData;
const usage = typeof keyData.usage === 'number' ? Number(keyData.usage.toFixed(4)) : (Number(keyData.usage) || 0);
const limit = typeof keyData.limit === 'number' ? Number(keyData.limit.toFixed(2)) : (keyData.limit !== null && keyData.limit !== undefined ? Number(keyData.limit) : null);
const remaining = typeof keyData.limit_remaining === 'number'
  ? Number(keyData.limit_remaining.toFixed(4))
  : (limit !== null ? Number(Math.max(0, limit - usage).toFixed(4)) : null);

const connectionId = 'or_conn_' + Math.random().toString(36).substring(2, 10);

return {
  success: true,
  connectionId: connectionId,
  connectionName: triggerInput.connectionName || 'Enterprise OpenRouter Gateway',
  productTag: 'SHARED_GATEWAY',
  totalUsage: usage,
  creditLimit: limit,
  remainingBalance: remaining,
  keyLabel: keyData.label || triggerInput.connectionName || 'Enterprise Key',
  isFreeTier: Boolean(keyData.is_free_tier),
  recordsIngested: 1,
  keysList: [{
    name: keyData.name || triggerInput.connectionName || 'Primary Key',
    label: keyData.label || '',
    usage: usage,
    limit: limit,
    remaining: remaining
  }],
  lastSyncedAt: new Date().toISOString()
};
